alter table public.service_tasks add column if not exists assigned_to_name text, add column if not exists assigned_by_name text;
update public.service_tasks t set assigned_to_name=coalesce(t.assigned_to_name,p.full_name),assigned_by_name=coalesce(t.assigned_by_name,a.full_name) from public.profiles p,public.profiles a where p.id=t.assigned_to and a.id=t.assigned_by;
alter table public.service_tasks alter column assigned_to drop not null;
alter table public.service_tasks alter column assigned_by drop not null;
alter table public.service_tasks drop constraint if exists service_tasks_assigned_to_fkey;
alter table public.service_tasks drop constraint if exists service_tasks_assigned_by_fkey;
alter table public.service_tasks add constraint service_tasks_assigned_to_fkey foreign key(assigned_to) references public.profiles(id) on delete set null;
alter table public.service_tasks add constraint service_tasks_assigned_by_fkey foreign key(assigned_by) references public.profiles(id) on delete set null;
alter table public.service_team add column if not exists member_name text;
update public.service_team st set member_name=p.full_name from public.profiles p where p.id=st.profile_id and st.member_name is null;
alter table public.service_team alter column profile_id drop not null;
alter table public.service_team drop constraint if exists service_team_profile_id_fkey;
alter table public.service_team add constraint service_team_profile_id_fkey foreign key(profile_id) references public.profiles(id) on delete set null;
alter table public.expenses drop constraint if exists expenses_created_by_fkey;
alter table public.expenses add constraint expenses_created_by_fkey foreign key(created_by) references public.profiles(id) on delete set null;
alter table public.service_images drop constraint if exists service_images_uploaded_by_fkey;
alter table public.service_images add constraint service_images_uploaded_by_fkey foreign key(uploaded_by) references public.profiles(id) on delete set null;
alter table public.service_records drop constraint if exists service_records_opened_by_fkey;
alter table public.service_records add constraint service_records_opened_by_fkey foreign key(opened_by) references public.profiles(id) on delete set null;
alter table public.service_records drop constraint if exists service_records_delivered_by_fkey;
alter table public.service_records add constraint service_records_delivered_by_fkey foreign key(delivered_by) references public.profiles(id) on delete set null;
alter table public.service_team drop constraint if exists service_team_assigned_by_fkey;
alter table public.service_team add constraint service_team_assigned_by_fkey foreign key(assigned_by) references public.profiles(id) on delete set null;
alter table public.service_updates drop constraint if exists service_updates_created_by_fkey;
alter table public.service_updates add constraint service_updates_created_by_fkey foreign key(created_by) references public.profiles(id) on delete set null;
alter table public.service_updates drop constraint if exists service_updates_edited_by_fkey;
alter table public.service_updates add constraint service_updates_edited_by_fkey foreign key(edited_by) references public.profiles(id) on delete set null;